    void irMenu(const String& id, const IrInfo* t, int n, Component* at) { auto* c = dynamic_cast<AudioParameterChoice*>(p.apvts.getParameter(id)); PopupMenu m; String g; PopupMenu sub; for (int i = 0; i <= n; ++i) { if (i == n || g != t[i].group) { if (g.isNotEmpty()) m.addSubMenu(g, sub); sub = PopupMenu(); if (i < n) g = t[i].group; } if (i < n) sub.addItem(i + 1, String(t[i].name) + (t[i].modeled ? "  (modeled)" : ""), true, i == c->getIndex()); } styled(m, at); m.showMenuAsync(PopupMenu::Options().withTargetComponent(at), [c](int x) { if (x > 0) { c->beginChangeGesture(); c->setValueNotifyingHost(c->convertTo0to1(float(x - 1))); c->endChangeGesture(); } }); }
