    void show(int i) { page = i; for (int t = 0; t < 4; ++t) { tabs[t].lit = t == i; tabs[t].repaint(); } bool m = i == 0; for (auto& c : cards) c->setVisible(m); for (auto* c : std::initializer_list<Component*> { &wet,&outK,&bayChip }) c->setVisible(m); for (auto& s : edit) s->setVisible(i == 1); for (auto& s : snap) s->setVisible(i == 1); for (auto& s : fx) s->setVisible(i == 2); for (auto& s : bayS) s->setVisible(i == 3); showBank(); refreshSnaps(); repaint(); }
