SpeakitEditor::SpeakitEditor(SpeakitProcessor& q) : AudioProcessorEditor(q), p(q) { d = std::make_unique<Impl>(q); addAndMakeVisible(*d); setResizable(true, true); setResizeLimits(520, 520, 1200, 1200); getConstrainer()->setFixedAspectRatio(1); setSize(880, 880); startTimerHz(24); }
SpeakitEditor::~SpeakitEditor() { stopTimer(); d = nullptr; }
void SpeakitEditor::resized() { if (d) { float k = getWidth() / 1932.f; d->setTransform(AffineTransform::scale(k)); d->skin.menuFont = 19.f / k; } }
void SpeakitEditor::setPage(int i) { d->show(i); }
void SpeakitEditor::testMenu(int i) { if (i == 0) d->preset.click(); else d->target[0].click(); }
void SpeakitEditor::timerCallback() { d->tick(); for (auto* c : d->getChildren()) if (dynamic_cast<Pad*>(c) && c->isVisible()) c->repaint(); }
